package com.truckload.controller;
import android.app.*;
import android.graphics.Color;
import android.os.SystemClock;
import android.view.*;
import android.widget.*;
import java.util.*;
/** Native driving, map and supervised bench controls. */
public final class FeaturePanels {
 private final MainActivity a;private final Telemetry m;private final List<Button> extended=new ArrayList<>(),benchOnly=new ArrayList<>(),driveModes=new ArrayList<>(),drivePatterns=new ArrayList<>();private final Map<String,TextView> labels=new HashMap<>();private final String[] patterns={"SOLID","PULSE","CHASE","ALTERNATE","BREATHE","RAINBOW"};private SeekBar driveBrightness,loadSlider,psiSlider;private boolean driveDirty=false,loadDragging=false,psiDragging=false,active=true;private long heartbeat=0;private AlertDialog benchDialog;private GpsMapView map;private Button color1,color2,start,stop,realOn,realOff;
 public FeaturePanels(MainActivity activity,Telemetry model){a=activity;m=model;}
 private TextView label(LinearLayout p,String id,String value){TextView t=a.text(value,13,0xffa2b1c4);labels.put(id,t);p.addView(t);return t;}
 private void say(String key,String value){TextView t=labels.get(key);if(t!=null)t.setText(value);}
 private Button feature(String text,Runnable action){Button b=a.button(text,action,false);extended.add(b);return b;}
 private Button benchButton(String text,String command){Button b=feature(text,()->a.send(command));benchOnly.add(b);return b;}
 public void driving(LinearLayout p){LinearLayout c=a.card(p,"Driving lights","Set the appearance here, then choose driving lights on, load mode or automatic GPS control.");label(c,"support","Connect to check firmware support.");a.pair(c,feature("Driving lights on",()->a.send("DRIVE_CONTROL|ON")),feature("Return to load",()->a.send("DRIVE_CONTROL|LOAD")));LinearLayout pair=(LinearLayout)c.getChildAt(c.getChildCount()-1);driveModes.add((Button)pair.getChildAt(0));driveModes.add((Button)pair.getChildAt(1));Button automatic=feature("Automatic with GPS",()->a.send("DRIVE_CONTROL|AUTO"));driveModes.add(automatic);a.addButton(c,automatic);label(c,"driveBrightness","Driving brightness · 55%");driveBrightness=new SeekBar(a);driveBrightness.setMin(1);driveBrightness.setMax(100);c.addView(driveBrightness);driveBrightness.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int v,boolean user){if(user){driveDirty=true;say("driveBrightness","Driving brightness · "+v+"%");}}});a.addButton(c,feature("Save driving brightness",()->a.send("SET_DRIVE_BRIGHTNESS|"+Math.max(1,Math.round(driveBrightness.getProgress()*255f/100f)))));color1=feature("Primary color",()->a.colorDialog(4));color2=feature("Secondary color",()->a.colorDialog(6));a.pair(c,color1,color2);a.gap(c,10);c.addView(a.text("Chase and alternating patterns use both colors. Rainbow uses its own spectrum.",12,0xffa2b1c4));String[] titles={"Solid","Gentle pulse","Chase","Alternating","Breathing","Rainbow"};for(int row=0;row<3;row++){final int i=row*2,j=i+1;Button b=feature(titles[i],()->a.send("SET_DRIVE_PATTERN|"+patterns[i])),d=feature(titles[j],()->a.send("SET_DRIVE_PATTERN|"+patterns[j]));drivePatterns.add(b);drivePatterns.add(d);a.pair(c,b,d);}StripPreview preview=new StripPreview(a,m,"",true);c.addView(preview,new LinearLayout.LayoutParams(-1,a.dp(83)));a.addButton(c,a.button("Open bench light tester",this::showBench,false));}
 public void loadExamples(LinearLayout p){LinearLayout c=a.card(p,"Load pattern examples","Animated examples only. These do not change the real weight or operate the strips.");String[] codes={"BAR","CENTER","PULSE","SOLID"},titles={"Progress bar","From center","Pulse","Solid color"};for(int i=0;i<4;i++){c.addView(a.text(titles[i],14,0xffedf3fa));c.addView(new StripPreview(a,m,codes[i],false),new LinearLayout.LayoutParams(-1,a.dp(83)));}}
 public void gpsMap(LinearLayout p){LinearLayout c=a.card(p,"GPS map","Blue marks the Heltec. The plant and its geofence are green. Drag to explore; map tiles need internet.");map=new GpsMapView(a);c.addView(map,new LinearLayout.LayoutParams(-1,a.dp(280)));LinearLayout buttons=a.row();a.pair(c,a.button("Zoom in",()->map.zoom(1),false),a.button("Zoom out",()->map.zoom(-1),false));a.addButton(c,a.button("Follow Heltec",()->map.follow(),false));label(c,"coordinates","Waiting for a real GPS fix. No location is simulated.");}
 public void showBench(){if(benchDialog!=null&&benchDialog.isShowing())return;LinearLayout p=a.vertical();p.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(8));p.addView(a.text("Test lights and real sensor diagnostics while parked. Simulated load and pressure below are labelled examples and never become real weight readings or calibration points.",13,0xffa2b1c4));label(p,"benchSupport","Connect a controller with bench-test firmware.");start=feature("Start bench test",()->a.send("BENCH|ON"));stop=feature("Stop bench test",()->a.send("BENCH|OFF"));a.pair(p,start,stop);label(p,"benchState","Bench test is off");a.pair(p,benchButton("Test load lights","BENCH_LIGHT|LOAD"),benchButton("Test driving lights","BENCH_LIGHT|DRIVE"));a.pair(p,benchButton("Test work lights","BENCH_LIGHT|WORK"),benchButton("All test lights off","BENCH_LIGHT|OFF"));a.gap(p,12);p.addView(a.text("Driving pattern for testing",14,0xffedf3fa));Spinner drive=new Spinner(a);ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,patterns);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);drive.setAdapter(adapter);drive.setSelection(Math.max(0,Arrays.asList(patterns).indexOf(m.drivePattern)));p.addView(drive);drive.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> v){}public void onItemSelected(android.widget.AdapterView<?> v,View view,int i,long id){if(m.bench&&!patterns[i].equals(m.drivePattern)){a.send("SET_DRIVE_PATTERN|"+patterns[i]);a.send("BENCH_LIGHT|DRIVE");}}});label(p,"benchLoad","SIMULATED load · 50%");loadSlider=new SeekBar(a);loadSlider.setMax(120);loadSlider.setProgress((int)m.benchPercent);p.addView(loadSlider);loadSlider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){loadDragging=true;}public void onStopTrackingTouch(SeekBar s){a.send("BENCH_LOAD|"+s.getProgress());loadDragging=false;}public void onProgressChanged(SeekBar s,int v,boolean user){if(user)say("benchLoad","SIMULATED load · "+v+"%");}});label(p,"benchPsi","SIMULATED pressure · 25 PSI");psiSlider=new SeekBar(a);psiSlider.setMax(100);psiSlider.setProgress((int)m.benchPsi);p.addView(psiSlider);psiSlider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){psiDragging=true;}public void onStopTrackingTouch(SeekBar s){a.send("BENCH_PSI|"+s.getProgress());psiDragging=false;}public void onProgressChanged(SeekBar s,int v,boolean user){if(user)say("benchPsi","SIMULATED pressure · "+v+" PSI");}});label(p,"benchEstimate","Simulated pressure → calibrated estimate: requires a calibrated trailer.");a.gap(p,14);p.addView(a.text("Real wired pressure sensor",17,0xffedf3fa));realOn=benchButton("Read wired sensor","BENCH_SENSOR|ON");realOff=benchButton("Sensor test off","BENCH_SENSOR|OFF");a.pair(p,realOff,realOn);label(p,"realDiagnostics","Real readings are off");p.addView(a.text("Enabling a sensor test does not change your normal sensor setting. Closing this screen, leaving the app or disconnecting stops the test. Firmware also stops tests after 15 seconds without a heartbeat.",12,0xffa2b1c4));ScrollView wrap=new ScrollView(a);wrap.addView(p);benchDialog=new AlertDialog.Builder(a).setTitle("Bench test · temporary").setView(wrap).setNegativeButton("Close / stop test",null).create();benchDialog.setOnDismissListener(d->{if(a.isConnected()&&m.extended)a.send("BENCH|OFF");extended.remove(start);extended.remove(stop);extended.removeAll(benchOnly);benchOnly.clear();loadSlider=psiSlider=null;});benchDialog.show();update();}
 public void update(){boolean available=a.isConnected()&&m.extended;for(Button b:extended){b.setEnabled(available);b.setAlpha(available?1:.45f);}say("support",!a.isConnected()?"Connect the Heltec to change driving settings.":m.extended?"Driving controls ready":"Firmware update required for driving patterns and bench tests.");say("benchSupport",!a.isConnected()?"Connect the Heltec to run tests.":!m.extended?"Install the companion firmware update to enable tests.":"Settings use the current trailer, colors and lighting patterns.");if(driveBrightness!=null){driveBrightness.setEnabled(available);if(!driveDirty){driveBrightness.setProgress(Math.max(1,Math.round(m.driveBrightness*100f/255)));say("driveBrightness","Driving brightness · "+driveBrightness.getProgress()+"%");}}for(int i=0;i<drivePatterns.size();i++)a.selected(drivePatterns.get(i),m.drivePattern.equals(patterns[i]));for(int i=0;i<driveModes.size();i++)a.selected(driveModes.get(i),m.driveControl.equals(new String[]{"ON","LOAD","AUTO"}[i]));if(color1!=null){color1.setText("Primary #"+m.colors.get("DRIVE"));color2.setText("Secondary #"+m.colors.get("DRIVE2"));}if(map!=null)map.position(m,a.isConnected());say("coordinates",a.isConnected()&&m.gpsFix?String.format(Locale.US,"Heltec: %.6f, %.6f",m.latitude,m.longitude):"Waiting for a real GPS fix. No location is simulated.");if(benchDialog!=null&&benchDialog.isShowing()){start.setEnabled(available&&!m.bench);stop.setEnabled(available&&m.bench);for(Button b:benchOnly)b.setEnabled(available&&m.bench);loadSlider.setEnabled(available&&m.bench);psiSlider.setEnabled(available&&m.bench);say("benchState",m.bench?"BENCH ACTIVE · "+m.benchMode+" · calibration capture locked":"Bench test is off");if(!loadDragging){loadSlider.setProgress((int)m.benchPercent);say("benchLoad",String.format(Locale.US,"SIMULATED load · %.0f%%",m.benchPercent));}if(!psiDragging){psiSlider.setProgress((int)m.benchPsi);say("benchPsi",String.format(Locale.US,"SIMULATED pressure · %.0f PSI",m.benchPsi));}say("benchEstimate",Double.isFinite(m.benchWeight)?String.format(Locale.US,"SIMULATED estimate: %.0f lb · %.1f%% of target",m.benchWeight,m.benchEstimate):"SIMULATED estimate: add at least two real calibration points to a trailer.");say("realDiagnostics",!m.bench||!m.benchSensor?"Real sensor test is off":String.format(Locale.US,"REAL sensor: %s\nADC: %s V · sensor: %s V\nPressure: %s PSI",m.sensor,number(m.adcVolts,3),number(m.sensorVolts,3),number(m.psi,1)));a.selected(realOn,m.benchSensor&&m.bench);a.selected(realOff,!m.benchSensor||!m.bench);}}
 private String number(double n,int decimals){return Double.isFinite(n)?String.format(Locale.US,"%."+decimals+"f",n):"—";}
 public void record(String type,String line){if(type.equals("CAPS")&&m.extended){a.send("GET_DRIVE_CONFIG");a.send("GET_BENCH_STATE");}if(line.startsWith("OK|SET_DRIVE_BRIGHTNESS"))driveDirty=false;}
 public void tick(){if(active&&a.isConnected()&&m.bench&&benchDialog!=null&&benchDialog.isShowing()&&SystemClock.elapsedRealtime()-heartbeat>4000){heartbeat=SystemClock.elapsedRealtime();a.send("BENCH_HEARTBEAT");}}
 public void active(boolean value){active=value;if(!value&&a.isConnected()&&m.extended)a.send("BENCH|OFF");}
 public void disconnected(){driveDirty=false;m.extended=false;m.bench=false;m.plant=false;m.plantLat=m.plantLon=Double.NaN;}
 public void close(){if(map!=null)map.close();if(benchDialog!=null)benchDialog.dismiss();}
}
